mapper.select:
select p.PORTFOLIO_ID as portfolioId, p.PORTFOLIO_NAME as portfolioName, fp.FINPROD_ID as finprodId, fp.FINPROD_MARKET_ID as finprodMarketId, fp.FINPROD_ABBR as finprodAbbr, fp.FINPROD_TYPE2, fpt.TYPE_8 as type8, T.TRADE_DATE as tradeDate, T.PS as ps, T.INV_AIM as invAim, (CASE WHEN fp.FINPROD_TYPE2 = 'F01' THEN T.SHARE_AMT * 100 ELSE T.SHARE_AMT END) as amount,
T.UNIT_CPRICE as tradePrice, T.UNIT_INT as accuir, T.TRADE_AMT as tradeAmt, T.MDATE as mdate, T.YIELD * 100 as yield, T.EXER_YIELD * 100 as exerYield FROM MOCK_PRODUCT_DEAL T left join PTL_PORTFOLIO p on T.PORTFOLIO_ID = p.PORTFOLIO_ID left join FIN_PRODUCT fp on T.FINPROD_ID = fp.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on T.FINPROD_ID = fpt.FINPROD_ID
T.MOCK_ID = #{mockId}

select m.MOCK_ID mockId, m.PORTFOLIO_ID portfolioId, p.PORTFOLIO_NAME portfolioName, m.MDATE mdate, m.AGAIN_INVEST_RATE * 100 againInvestRate, m.FINAN_COST * 100 finanCost, m.MOCK_YIELD * 100 mockYield, m.CREATE_TIME mockDate from MOCK_TEST m inner join PTL_PORTFOLIO p on m.PORTFOLIO_ID = p.PORTFOLIO_ID
m.CREATE_USER = #{loginUserName}
and DATE_FORMAT(m.MOCK_DATE, '%Y-%m-%d') >= #{dataDateStart}
and DATE_FORMAT(m.MOCK_DATE, '%Y-%m-%d') <= #{dataDateEnd}
and m.PORTFOLIO_ID = #{portfolioId}
order by m.CREATE_TIME desc

SELECT A.FINPROD_ID id, A.FINPROD_ABBR text, A.FINPROD_ABBR, A.FINPROD_MARKET_ID, A.FINPROD_ID, A.CCY, B.TYPE_8, DATE_FORMAT(A.MDATE, '%Y-%m-%d') MDATE FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID
( A.FINPROD_MARKET_ID LIKE CONCAT('%', #{search},'%') or A.FINPROD_NAME LIKE CONCAT('%', #{search}, '%') )
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 in
#{item}
